/** Public entry point — the only module consumers/docs should import from. */

export { useDataGridHistory, type HistorySkip, type RecordedChange, type UseDataGridHistoryOptions, type UseDataGridHistoryResult } from "./use-data-grid-history";
export { useDataGridState, type UseDataGridStateOptions, type UseDataGridStateResult } from "./use-data-grid-state";

// Relative on purpose: the shadcn CLI rewrites import paths, never augmentation module names.
declare module "../data-grid/types" {
  interface GridActions {
    undo: true;
    redo: true;
  }
}

/** Offers the `undo`/`redo` global-shortcut flags — this add-on is what makes them do anything. */
declare module "../data-grid/keyboard/global-shortcuts" {
  interface DataGridGlobalShortcutActions {
    undo: boolean;
    redo: boolean;
  }
}

import type { Keymap } from "@/registry/default/components/data-grid/data-grid";

export const HISTORY_KEYMAP: Keymap = {
  undo: ["mod+z"],
  redo: ["mod+y", "mod+shift+z"],
};

"use client";

import { useCallback, useEffect, useMemo, useRef, useState, type ComponentType, type ReactNode } from "react";
import { useDataGridApi, useDataGridFilterState, useDataGridSearchText, useDataGridSortState, type DataChange, type DataGridApi, type DataGridPlugin, type ServerSpec } from "@/registry/default/components/data-grid/data-grid";
import { HISTORY_KEYMAP } from "./history-keymap";
import { isDev, createHistory, buildRollback, rebaseOntoCurrent, useDataGridAnnounce, useDataGridSelector } from "@/registry/default/components/data-grid/data-grid-sdk";

type RecordSources<TData> =
  | readonly DataChange<TData>["source"][]
  | ((defaults: readonly DataChange<TData>["source"][]) => readonly DataChange<TData>["source"][]);

/** Options for {@link useDataGridHistory}. */
export type UseDataGridHistoryOptions<TData> = {
  /** Maximum number of entries kept on the undo stack (default `100`); oldest entries are dropped past this. A change between renders keeps the entries and trims to the new value. */
  capacity?: number;
  /**
   * Identity of the dataset; a change between renders clears both stacks, so undo after a dataset
   * swap cannot reinsert rows from the old dataset. A function receives the grid's sort, filters,
   * and search text and returns the key, so `datasetKey: serverSpecKey` clears the stacks on every
   * server spec change and needs no server hook result. Omit it and reset with `clear()` instead.
   */
  datasetKey?: string | number | ((spec: ServerSpec) => string | number);
  /**
   * Which `DataChange.source` values go on the undo stack. Defaults to
   * `["edit", "paste", "fill", "delete", "cut", "row-operation", "import", "replace", "app"]`: `"stream"` stays
   * out because a 100-updates/s `updateCells` feed would otherwise evict the user's whole undo
   * stack within seconds. Pass a list to replace the set, or a function of the defaults to edit it, for
   * example `(defaults) => [...defaults, "stream"]` to record streams too. `"history"`, `"rollback"`,
   * `"merge"`, and `"id-swap"` are never recorded, whatever the list says — that is what keeps an undo
   * from pushing a second entry.
   */
  recordSources?: RecordSources<TData>;
  /**
   * Called when `undo` or `redo` finds a row its change needs missing from `data`, and applies nothing.
   * `"rows-not-loaded"`: `data` has holes (scroll mode) or holds part of the result (`totalRowCount` above its length or `null`, such as one
   * server page or a cursor source); the entry stays, so the same call works after the rows load.
   * `"rows-gone"`: `data` holds the whole result and lacks the rows; the entry is dropped. The live region announces both.
   * A throw is logged and does not stop the grid.
   */
  onSkip?: (ctx: HistorySkip) => void;
};

/** What {@link UseDataGridHistoryOptions.onSkip} receives. */
export type HistorySkip = {
  direction: "undo" | "redo";
  reason: "rows-not-loaded" | "rows-gone";
  /** Ids of the rows the change needs and `data` lacks. */
  rowIds: readonly string[];
};

/**
 * The ids `change` needs that `data` lacks (an insert needs none), and whether `data` has holes.
 * `Array.prototype.some` skips holes, so the scan tests indices.
 */
function findMissingRows<TData>(
  change: DataChange<TData>,
  data: readonly unknown[],
  getRowId: (row: never, index: number) => string,
): { missing: string[]; hasHoles: boolean } {
  const needed = new Set<string>();
  for (const op of change.ops) if (op.type !== "insert") needed.add(op.rowId);
  let hasHoles = false;
  for (let i = 0; i < data.length; i++) {
    const row = data[i];
    if (!(i in data) || row === undefined) hasHoles = true;
    else if (needed.size > 0) needed.delete(getRowId(row as never, i));
  }
  return { missing: [...needed], hasHoles };
}

/** Sources `useDataGridHistory` records when `recordSources` is omitted — everything a user did on purpose (`"history"` is skipped before the filter runs). */
const DEFAULT_RECORD_SOURCES: readonly DataChange<unknown>["source"][] = [
  "edit",
  "paste",
  "fill",
  "delete",
  "cut",
  "row-operation",
  "import",
  "replace",
  "app",
];

const NOT_MOUNTED_CHECK_MS = 2000;

/** Return value of {@link useDataGridHistory}. */
export type UseDataGridHistoryResult<TData> = {
  /** One entry of the grid's `plugins` prop — the plugin's `onDataChange` observer records the grid's data changes, its `undo`/`redo` commands back the mod+Z/mod+Shift+Z bindings, and its `Mount` hands the grid's api handle to the imperative triggers below. Stable for the hook's lifetime. An inline `plugins={[plugin]}` is fine: re-resolution is gated on entry identity (name + member references), not on the array's. */
  plugin: DataGridPlugin<TData>;
  /** Imperative undo (a toolbar button outside the keyboard bindings); no-op when nothing to undo, the grid is not mounted yet, or the grid is read-only. Applies nothing and calls `onSkip` when a needed row is missing. */
  undo: () => void;
  /** Imperative redo; see {@link UseDataGridHistoryResult.undo}. */
  redo: () => void;
  /** `true` when `undo` would do something now: an entry exists and the grid is not `readOnly`. */
  canUndo: boolean;
  /** `true` when `redo` would do something now: an entry exists and the grid is not `readOnly`. */
  canRedo: boolean;
  /** Number of entries on the undo stack, also while the grid is `readOnly`; 0 when there is nothing to undo. */
  historySize: number;
  /** Clears both stacks. A dataset change clears them itself when `datasetKey` changes; use `clear` for an imperative reset. */
  clear: () => void;
  /**
   * Reverts `change` (the object an `onDataChange` handler received) after its save failed: applies the
   * inverse with `source: "rollback"` and drops the entry from the stacks, so no dead undo step remains.
   * A cell reverts only while it still holds the change's value, so later edits survive. A change the
   * user already undid is dropped without a write. A whole-row update reverts only while the row is shallow-equal to the change's row. No-op when the grid is not mounted yet or is read-only.
   */
  rollback: (change: DataChange<TData>) => void;
  /**
   * Applies a programmatic change (the consumer-built operation batch) to the grid as one write AND
   * registers it as one undo entry — `commitChange` with `source: "app"`, which the observer
   * records like any user gesture. Returns `false` when nothing is written (the grid is not mounted yet, is `readOnly`, or every operation was an insert of a row `data` already holds), `true` otherwise.
   * `label` is an optional human-readable entry label.
   */
  record: (change: RecordedChange<TData>, label?: string) => boolean;
};

/** The change `record` takes. `source` is optional: `record` stores every entry as `"app"`. */
export type RecordedChange<TData> = Omit<DataChange<TData>, "source"> & { source?: DataChange<TData>["source"] };

/**
 * Operation-based undo/redo as a grid plugin. Records the grid's own `onDataChange` stream (the observer
 * runs after the store write and after the consumer's `onDataChange`), and undoes/redoes by
 * applying the inverted operation batch back through the grid's `commitChange` (an update with `cells` writes only those cells onto the current row) — one write, one emit,
 * so a controlled `data` prop sees the same change the user made.
 *
 * Design: the plugin does not take `data`/`setData` — the grid's store is the write target, and
 * the consumer's controlled-data echo (their `onDataChange` calling their own state setter)
 * stays exactly where it always was. `undo`/`redo` applied through the grid carry
 * `source: "history"`, which the observer skips, so each undo or redo records no second entry.
 */
export function useDataGridHistory<TData>(opts: UseDataGridHistoryOptions<TData> = {}): UseDataGridHistoryResult<TData> {
  const { capacity, datasetKey, recordSources } = opts;
  const onSkipRef = useRef(opts.onSkip);
  onSkipRef.current = opts.onSkip;
  const warnedSparseData = useRef(false);
  const warnedNotMounted = useRef(false);
  const history = useMemo(() => createHistory<TData>({ capacity }), []);
  history.setCapacity(capacity ?? 100);
  // history's canUndo/canRedo are getters on a mutable object; this forces a re-render
  // after every mutating call so callers see them update even when nothing else re-renders
  // this hook (e.g. `clear()`, or a consumer setter that dedupes identical arrays).
  const [, forceUpdate] = useState(0);

  // stale entries reference the old dataset: undo after a swap would resurrect dead rows
  const fixedKey = typeof datasetKey === "function" ? undefined : datasetKey;
  const prevDatasetKey = useRef(fixedKey);
  useEffect(() => {
    if (prevDatasetKey.current === fixedKey) return;
    prevDatasetKey.current = fixedKey;
    history.clear();
    forceUpdate((n) => n + 1);
  }, [fixedKey, history]);
  const specKeyRef = useRef(typeof datasetKey === "function" ? datasetKey : null);
  specKeyRef.current = typeof datasetKey === "function" ? datasetKey : null;
  const historyRef = useRef(history);
  historyRef.current = history;

  const recorded = useMemo(
    () =>
      new Set<DataChange<TData>["source"]>(
        typeof recordSources === "function" ? recordSources(DEFAULT_RECORD_SOURCES) : (recordSources ?? DEFAULT_RECORD_SOURCES),
      ),
    [recordSources],
  );
  const recordedRef = useRef(recorded);
  recordedRef.current = recorded;

  // The grid's imperative handle, stashed by the plugin's Mount (and refreshed by every
  // command/observer ctx): the imperative `undo`/`redo`/`record` triggers below run through it.
  const apiRef = useRef<DataGridApi<TData> | null>(null);
  const announceRef = useRef<ReturnType<typeof useDataGridAnnounce> | null>(null);
  const readOnlyRef = useRef(false);

  const warnNotMounted = useCallback((method: string) => {
    if (warnedNotMounted.current || !isDev()) return;
    warnedNotMounted.current = true;
    console.warn(`[data-grid-history] ${method}() ran before the history plugin mounted, so it did nothing. Pass "plugin" (or "plugins" from useDataGridState) to the grid, and keep it in a plugins prop that you set after a spread.`);
  }, []);

  useEffect(() => {
    if (!isDev()) return;
    const timer = setTimeout(() => {
      if (apiRef.current || warnedNotMounted.current) return;
      warnedNotMounted.current = true;
      console.warn(`[data-grid-history] The history plugin never mounted, so undo and redo do nothing. Pass "plugin" (or "plugins" from useDataGridState) to the grid's plugins prop.`);
    }, NOT_MOUNTED_CHECK_MS);
    return () => clearTimeout(timer);
  }, []);

  const applyHistoryChange = useCallback(
    (direction: HistorySkip["direction"]) => {
      const api = apiRef.current;
      if (!api) return warnNotMounted(direction);
      const state = api.store.getState();
      // A read-only grid refuses the revert, so popping the entry would only lose it.
      if (state.readOnly) return;
      const rebase = (entry: DataChange<TData>) => rebaseOntoCurrent(entry, state);
      const change = direction === "undo" ? history.undo(rebase) : history.redo(rebase);
      if (!change) return;
      const { missing, hasHoles: holes } = findMissingRows(change, state.data, state.getRowId);
      // an unknown count (`null`, a cursor source) or a count above the loaded rows means `data` holds a part of the result
      const hasHoles = holes || state.totalRowCount === null || (typeof state.totalRowCount === "number" && state.totalRowCount > state.data.length);
      if (!warnedSparseData.current && holes && missing.length > 0 && isDev()) {
        warnedSparseData.current = true;
        console.warn(
          "[data-grid-history] undo ran over a sparse (lazy) data array: unloaded rows are holes, so an undo that needs them is blocked and keeps its entry. Use a hole-tolerant getRowId and pass a datasetKey (or call clear()) when server.refresh() replaces the rows or the dataset changes.",
        );
      }
      if (missing.length === 0) {
        api.actions.commitChange(change);
        forceUpdate((n) => n + 1);
        return;
      }
      if (hasHoles) history.restore(change);
      else history.discard(change);
      forceUpdate((n) => n + 1);
      announceRef.current?.("historyBlocked", missing.length, hasHoles);
      try {
        onSkipRef.current?.({ direction, reason: hasHoles ? "rows-not-loaded" : "rows-gone", rowIds: missing });
      } catch (error) {
        console.error("[data-grid-history] onSkip threw:", error);
      }
    },
    [history, warnNotMounted],
  );

  const undo = useCallback(() => applyHistoryChange("undo"), [applyHistoryChange]);
  const redo = useCallback(() => applyHistoryChange("redo"), [applyHistoryChange]);

  const clear = useCallback(() => {
    history.clear();
    forceUpdate((n) => n + 1);
  }, [history]);

  const rolledBack = useMemo(() => new WeakSet<DataChange<TData>>(), []);

  const rollback = useCallback(
    (change: DataChange<TData>) => {
      const api = apiRef.current;
      if (!api) return warnNotMounted("rollback");
      if (api.store.getState().readOnly) return;
      rolledBack.add(change);
      const undoSize = history.size;
      const found = history.discard(change);
      const alreadyUndone = found && history.size === undoSize;
      if (!alreadyUndone) api.actions.commitChange(buildRollback(change, api.store.getState()));
      forceUpdate((n) => n + 1);
    },
    [history, rolledBack, warnNotMounted],
  );

  const record = useCallback(
    (change: RecordedChange<TData>, label?: string) => {
      const api = apiRef.current;
      if (!api) {
        warnNotMounted("record");
        return false;
      }
      if (api.store.getState().readOnly) return false;
      const fresh = withoutPresentInserts(api.store.getState(), { ...change, source: "app" });
      if (fresh.ops.length === 0) return false;
      // `source: "app"` tags the imperative entry (see DataChange.source); the observer records it
      api.actions.commitChange({ ...fresh, source: "app", ...(label !== undefined ? { label } : {}) });
      forceUpdate((n) => n + 1);
      return true;
    },
    [history, warnNotMounted],
  );

  // The Mount must keep ONE identity for the hook's lifetime (a fresh component type per render
  // would remount it); the api stash touches no hook state, so a once-created closure is safe.
  const mountRef = useRef<ComponentType | null>(null);
  if (mountRef.current === null) {
    const ref = apiRef;
    const announce = announceRef;
    mountRef.current = function HistoryApiStash(): ReactNode {
      ref.current = useDataGridApi<TData>();
      announce.current = useDataGridAnnounce();
      const readOnly = useDataGridSelector((s) => s.readOnly);
      useEffect(() => {
        if (readOnlyRef.current === readOnly) return;
        readOnlyRef.current = readOnly;
        forceUpdate((n) => n + 1);
      }, [readOnly]);
      const sorts = useDataGridSortState();
      const filters = useDataGridFilterState();
      const searchText = useDataGridSearchText();
      const specKey = useMemo(() => specKeyRef.current?.({ sorts, filters, searchText }), [sorts, filters, searchText]);
      const lastSpecKey = useRef(specKey);
      useEffect(() => {
        if (lastSpecKey.current === specKey) return;
        lastSpecKey.current = specKey;
        historyRef.current.clear();
        forceUpdate((n) => n + 1);
      }, [specKey]);
      return null;
    };
  }

  const plugin = useMemo<DataGridPlugin<TData>>(
    () => ({
      name: "history",
      onDataChange: (next, change, ctx) => {
        if (change.source === "rollback" || change.source === "merge") {
          const { reverts, serverRowIds } = change;
          const revertedEntry =
            reverts !== undefined && (change.source === "rollback" ? history.restore(reverts) || history.discard(reverts) : history.discard(reverts));
          const prunedEntries = serverRowIds !== undefined && history.dropRows(serverRowIds);
          if (revertedEntry || prunedEntries) forceUpdate((n) => n + 1);
          return;
        }
        if (change.source === "id-swap") {
          const swapped = new Map<unknown, number>();
          for (const op of change.ops) if (op.type === "update") swapped.set(op.row, -1);
          next.forEach((row, index) => {
            if (swapped.get(row) === -1) swapped.set(row, index);
          });
          const getRowId = ctx.api.store.getState().getRowId;
          const swaps = change.ops.flatMap((op) =>
            op.type === "update" ? [{ oldId: op.rowId, newId: getRowId(op.row, Math.max(0, swapped.get(op.row) ?? 0)), oldRow: op.prev, newRow: op.row }] : [],
          );
          if (history.replaceRowIds(swaps)) forceUpdate((n) => n + 1);
          return;
        }
        if (change.source === "history") return;
        if (recordedRef.current.has(change.source) && !rolledBack.has(change)) history.push(change);
        forceUpdate((n) => n + 1);
      },
      commands: {
        undo: {
          when: (ctx) => !ctx.readOnly,
          run: (ctx) => {
            apiRef.current = ctx.api;
            undo();
          },
        },
        redo: {
          when: (ctx) => !ctx.readOnly,
          run: (ctx) => {
            apiRef.current = ctx.api;
            redo();
          },
        },
      },
      keymap: HISTORY_KEYMAP,
      Mount: mountRef.current ?? undefined,
    }),
    [history, rolledBack, undo, redo, mountRef.current],
  );

  return {
    plugin,
    undo,
    redo,
    canUndo: history.canUndo && !readOnlyRef.current,
    canRedo: history.canRedo && !readOnlyRef.current,
    historySize: history.size,
    clear,
    rollback,
    record,
  };
}

/** Drops an insert whose row id `data` already holds (the caller applied it first), so `record` never writes a row twice; warns once in development. */
function withoutPresentInserts<TData>(state: { data: readonly unknown[]; getRowId: (row: unknown, index: number) => string }, change: DataChange<TData>): DataChange<TData> {
  if (!change.ops.some((op) => op.type === "insert")) return change;
  const present = new Set(state.data.map((row, index) => (row === undefined ? "" : state.getRowId(row, index))));
  const ops = change.ops.filter((op) => op.type !== "insert" || !present.has(op.rowId));
  if (ops.length === change.ops.length) return change;
  if (isDev()) console.warn("[data-grid-history] record() skipped an insert of a row that data already holds. record() writes the change itself, so the call is safe, but you do not need to apply it to your own array first.");
  return { ...change, ops };
}

"use client";

import { useCallback, useState } from "react";
import { type DataChange, type DataGridPlugin } from "@/registry/default/components/data-grid/data-grid";
import { useDataGridHistory, type RecordedChange, type UseDataGridHistoryOptions } from "./use-data-grid-history";

/** Options for {@link useDataGridState}: every `useDataGridHistory` option, plus `getRowId` and `plugins`. */
export type UseDataGridStateOptions<TData> = UseDataGridHistoryOptions<TData> & {
  /** Row identity; defaults to the row's `id` field, like `DataGrid`'s `getRowId`. */
  getRowId?: (row: TData, index: number) => string;
  /** Other plugins of the grid. The returned `plugins` holds them, then the history plugin, so the spread stays complete. An inline array is fine: equal entries keep the identity. An inline plugin object is a new plugin on every render, so define it at module scope or memoize it. */
  plugins?: readonly DataGridPlugin<TData>[];
};

/** Return value of {@link useDataGridState}, spreadable straight onto `<DataGrid {...grid} />`. */
export type UseDataGridStateResult<TData> = {
  data: readonly TData[];
  getRowId?: (row: TData, index: number) => string;
  /** Writes the grid's next array back into the hook-owned state — the controlled-data echo the undo/redo flow relies on. */
  onDataChange: (next: readonly TData[], change: DataChange<TData>) => void;
  /** The grid's `plugins` prop: the `plugins` option, then the history plugin (observer + `undo`/`redo` commands + api stash). */
  plugins: readonly DataGridPlugin<TData>[];
  /**
   * For a toolbar's undo/redo buttons, outside the spreadable `DataGrid` props. `clear` empties
   * both stacks for an imperative reset — it lives on this sub-object, not the
   * spreadable top level, to avoid a future prop-name collision on the `<DataGrid {...grid} />`
   * spread.
   */
  history: {
    canUndo: boolean;
    canRedo: boolean;
    /** Number of entries on the undo stack; 0 when there is nothing to undo. */
    historySize: number;
    undo: () => void;
    redo: () => void;
    clear: () => void;
    /**
     * Applies a programmatic change (the consumer-built operation batch) to the grid AND registers it as
     * one undo entry — one `commitChange` write, recorded by the history plugin's observer.
     * Returns the same result as `useDataGridHistory`'s `record`.
     */
    record: (change: RecordedChange<TData>, label?: string) => boolean;
    /** Reverts a change whose save failed; see `useDataGridHistory`'s `rollback`. */
    rollback: (change: DataChange<TData>) => void;
  };
};

const NO_PLUGINS: readonly never[] = [];

const entryIds = new WeakMap<object, number>();
let nextEntryId = 0;

function entryIdOf(entry: object): number {
  let id = entryIds.get(entry);
  if (id === undefined) entryIds.set(entry, (id = nextEntryId++));
  return id;
}

class EntriesHolder<T> {
  private key: string | null = null;
  private entries: readonly T[] = [];

  /** The entries held for `key`: the last entries with an equal key, so a new array of equal entries keeps the identity. */
  hold(key: string, entries: readonly T[]): readonly T[] {
    if (key !== this.key) [this.key, this.entries] = [key, entries];
    return this.entries;
  }
}

// Keyed by entry identity and held outside state, so a new inline entry on every render gives a new array instead of a render loop.
function useStableEntries<T extends object>(entries: readonly T[]): readonly T[] {
  const [holder] = useState(() => new EntriesHolder<T>());
  return holder.hold(entries.map(entryIdOf).join(","), entries);
}

/**
 * Quick-start grid state with undo/redo: wires `useState` + {@link useDataGridHistory}
 * into one spreadable object.
 *
 * The hook owns the array between renders and spreads it into the grid as a controlled `data` prop.
 * Do not pass `defaultData` or your own `data` alongside the spread. `useDataGridHistory` alone
 * also gives undo/redo to a grid that owns `defaultData`. `defaultRows` seeds the state once; later
 * changes to it are ignored.
 *
 * ```tsx
 * const grid = useDataGridState(rows, { getRowId: (r) => r.id });
 * <DataGrid {...grid} columns={columns} />
 * ```
 */
export function useDataGridState<TData>(
  defaultRows: readonly TData[],
  opts: UseDataGridStateOptions<TData> = {},
): UseDataGridStateResult<TData> {
  const { getRowId, plugins: extraPlugins = NO_PLUGINS, ...historyOptions } = opts;
  const [data, setData] = useState<readonly TData[]>(defaultRows);
  const history = useDataGridHistory<TData>(historyOptions);
  // stable identity: useDataGridRowIdToViewRow keys its O(n) Map build on getRowId identity.
  const wrappedGetRowId = useCallback((row: TData, index: number) => getRowId!(row, index), [getRowId]);
  const gridGetRowId = getRowId ? wrappedGetRowId : undefined;

  const onDataChange = useCallback((next: readonly TData[]) => {
    setData(next);
  }, []);

  const historyPlugin = history.plugin;
  // the config phase keys its sync on array identity, so equal entries keep the last array
  const plugins = useStableEntries([...extraPlugins, historyPlugin]);

  return {
    data,
    getRowId: gridGetRowId,
    onDataChange,
    plugins,
    history: {
      canUndo: history.canUndo,
      canRedo: history.canRedo,
      historySize: history.historySize,
      undo: history.undo,
      redo: history.redo,
      clear: history.clear,
      record: history.record,
      rollback: history.rollback,
    },
  };
}
